#pragma once
#include "business_store.hpp"
namespace accountAnalysis {
inline QJsonValue known(const QJsonValue& v,bool positive=false){return v.isDouble()&&std::isfinite(v.toDouble())&&std::abs(v.toDouble())<=1e15&&(!positive||v.toDouble()>=0)?v:QJsonValue(QJsonValue::Null);}
inline QJsonValue add(const QJsonValue& a,const QJsonValue& b){return a.isDouble()&&b.isDouble()?QJsonValue(business::rounded(a.toDouble()+b.toDouble())):QJsonValue(QJsonValue::Null);}
inline QJsonObject evaluate(const QJsonObject& account,const QJsonArray& trades,const QJsonObject& quotes,const QJsonArray& reports){
 QString id=account["id"].toString();business::require(!id.isEmpty(),"请选择明确账户");auto p=business::portfolio(trades,quotes,id);auto cash=known(account["cashBalance"],true),assets=add(p["marketValue"],cash),totalPnl=add(p["realized"],p["unrealized"]);QJsonArray positions;
 for(auto v:p["positions"].toArray()){auto row=v.toObject();row["costWeightPercent"]=p["cost"].toDouble()>0?QJsonValue(business::rounded(row["cost"].toDouble()/p["cost"].toDouble()*100)):QJsonValue(QJsonValue::Null);row["marketWeightPercent"]=assets.isDouble()&&assets.toDouble()>0&&row["marketValue"].isDouble()?QJsonValue(business::rounded(row["marketValue"].toDouble()/assets.toDouble()*100)):QJsonValue(QJsonValue::Null);row["totalPnl"]=add(row["realized"],row["unrealized"]);auto quote=quotes[row["instrumentId"].toString()].toObject();row["quoteCached"]=quote["cached"].toBool();row["quoteSource"]=quote["source"];positions.append(row);}
 QList<QJsonObject> events;for(auto v:trades)if(v.toObject()["accountId"].toString()==id)events<<v.toObject();std::stable_sort(events.begin(),events.end(),[](const auto& a,const auto& b){return a["date"].toString()<b["date"].toString();});QJsonArray cashPath;double cumulative=0;bool complete=true;for(const auto& t:events){QString side=t["side"].toString();auto amount=known(t["amount"],true);if(!amount.isDouble()){auto q=known(t["quantity"],true),price=known(t["price"],true),fee=known(t["fee"],true),tax=known(t["tax"],true);if(side=="buy"&&q.isDouble()&&price.isDouble()&&fee.isDouble())amount=business::rounded(q.toDouble()*price.toDouble()+fee.toDouble());if(side=="sell"&&q.isDouble()&&price.isDouble()&&fee.isDouble()&&tax.isDouble())amount=business::rounded(q.toDouble()*price.toDouble()-fee.toDouble()-tax.toDouble());if(side=="dividend"&&q.isDouble()&&price.isDouble())amount=business::rounded(q.toDouble()*price.toDouble());if(side=="fee"&&fee.isDouble())amount=fee;}
 auto delta=amount.isDouble()?QJsonValue((side=="buy"||side=="fee"?-1:1)*amount.toDouble()):QJsonValue(QJsonValue::Null);if(delta.isDouble())cumulative+=delta.toDouble();else complete=false;cashPath.append(QJsonObject{{"tradeId",t["id"]},{"date",t["date"]},{"instrumentId",t["instrumentId"]},{"side",side},{"cashDelta",delta},{"cumulativeRecordedFlow",complete?QJsonValue(business::rounded(cumulative)):QJsonValue(QJsonValue::Null)}});}
 QList<QJsonObject> history;for(auto v:reports){const auto report=v.toObject();if(report["accountId"].toString()!=id||report["legacySource"]!="portfolio_snapshots")continue;const auto raw=report["legacyOriginal"].toObject();auto date=raw["snapshot_date"].toString();auto cashValue=known(raw["cash_balance"],true),market=known(raw["total_market_value"],true),asset=known(raw["total_assets"],true);bool dateValid=date.size()==10&&QDate::fromString(date,Qt::ISODate).isValid();history<<QJsonObject{{"reportId",report["id"]},{"date",date},{"dateValid",dateValid},{"cashBalance",cashValue},{"marketValue",market},{"totalAssets",asset},{"totalPnl",known(raw["total_pnl"])},{"arithmeticConsistent",cashValue.isDouble()&&market.isDouble()&&asset.isDouble()&&std::abs(asset.toDouble()-cashValue.toDouble()-market.toDouble())<=.05},{"sourceLabel",raw["source_label"]},{"original",raw}};}
 std::stable_sort(history.begin(),history.end(),[](const auto& a,const auto& b){return a["date"].toString()<b["date"].toString();});QJsonArray snapshots;QJsonValue previous(QJsonValue::Null);for(auto row:history){auto value=row["dateValid"].toBool()&&row["arithmeticConsistent"].toBool()?row.value("totalAssets"):QJsonValue(QJsonValue::Null);row["assetChange"]=value.isDouble()&&previous.isDouble()?QJsonValue(business::rounded(value.toDouble()-previous.toDouble())):QJsonValue(QJsonValue::Null);row["isPerformanceReturn"]=false;previous=value;snapshots.append(row);}
 return {{"schema","native-account-analysis/v1"},{"accountId",id},{"positions",positions},{"cost",p["cost"]},{"realized",p["realized"]},{"unrealized",p["unrealized"]},{"fees",p["fees"]},{"marketValue",p["marketValue"]},{"cashBalance",cash},{"cashAsOf",account["cashAsOf"]},{"totalAssets",assets},{"totalPnl",totalPnl},{"cashPath",cashPath},{"recordedCashFlow",complete?QJsonValue(business::rounded(cumulative)):QJsonValue(QJsonValue::Null)},{"cashFlowComplete",complete},{"history",snapshots},{"performanceReturn",QJsonValue(QJsonValue::Null)},{"boundary","移动加权成本与已实现/浮动盈亏沿旧账本。净现金流只反映记录的买卖/分红/费用，不推断期初现金或外部出入金；历史只用原始快照，资产变化不是净收益率。现金与行情时点未统一。"}};
}
}
